insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('cc6289d9-6f4d-5e05-a5d4-1f3c3850b5ed', '00d139c6-357b-5ca0-ab19-e2369aebe747', '65a56281-9deb-5f5b-ac26-255c32357f12', 'fcb85bae-5281-5f3b-aea6-56dfce64f647', 'In packet switching…', '["Packets may take different routes and are reassembled at the destination","Data must be sent in one piece","No headers are used","A dedicated path is reserved for the whole communication"]'::jsonb, 'This uses the network efficiently.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
